package org.apache.commons.cli;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.Method;

import static org.junit.jupiter.api.Assertions.*;

class DeprecatedAttributesTest {

    private Constructor<DeprecatedAttributes> getConstructor() throws NoSuchMethodException {
        Constructor<DeprecatedAttributes> ctor =
                DeprecatedAttributes.class.getDeclaredConstructor(String.class, String.class, boolean.class);
        ctor.setAccessible(true);
        return ctor;
    }

    @Test
    void toString_defaultAndDefaultField() throws Exception {
        Constructor<DeprecatedAttributes> ctor = getConstructor();
        DeprecatedAttributes instance = ctor.newInstance("", "", false);
        assertEquals("Deprecated", instance.toString());

        // Verify the DEFAULT static field yields the same string
        Field defaultField = DeprecatedAttributes.class.getDeclaredField("DEFAULT");
        defaultField.setAccessible(true);
        Object defaultObj = defaultField.get(null);
        assertNotNull(defaultObj);
        assertEquals("Deprecated", defaultObj.toString());
    }

    @Test
    void toString_forRemovalOnly() throws Exception {
        Constructor<DeprecatedAttributes> ctor = getConstructor();
        DeprecatedAttributes instance = ctor.newInstance("", "", true);
        assertEquals("Deprecated for removal", instance.toString());
    }

    @Test
    void toString_sinceOnly() throws Exception {
        Constructor<DeprecatedAttributes> ctor = getConstructor();
        DeprecatedAttributes instance = ctor.newInstance("", "1.0", false);
        assertEquals("Deprecated since 1.0", instance.toString());
    }

    @Test
    void toString_descriptionOnly() throws Exception {
        Constructor<DeprecatedAttributes> ctor = getConstructor();
        DeprecatedAttributes instance = ctor.newInstance("some description", "", false);
        assertEquals("Deprecated: some description", instance.toString());
    }

    @Test
    void toString_allOptionsCombined() throws Exception {
        Constructor<DeprecatedAttributes> ctor = getConstructor();
        DeprecatedAttributes instance = ctor.newInstance("detailed", "2.1", true);
        assertEquals("Deprecated for removal since 2.1: detailed", instance.toString());
    }

    @Test
    void toString_handlesNullsConvertedToEmpty() throws Exception {
        // Pass nulls to constructor (private) to ensure toEmpty conversion happens and branches for emptiness are correct
        Constructor<DeprecatedAttributes> ctor = getConstructor();
        DeprecatedAttributes instanceNulls = ctor.newInstance(null, null, false);
        assertEquals("Deprecated", instanceNulls.toString());

        DeprecatedAttributes instanceNullDesc = ctor.newInstance(null, "3.0", false);
        assertEquals("Deprecated since 3.0", instanceNullDesc.toString());

        DeprecatedAttributes instanceNullSince = ctor.newInstance("descr", null, false);
        assertEquals("Deprecated: descr", instanceNullSince.toString());
    }

    @Test
    void invokePrivateToEmptyDirectly() throws Exception {
        // Use reflection to call private toEmpty method to ensure its behavior is correct
        Constructor<DeprecatedAttributes> ctor = getConstructor();
        DeprecatedAttributes instance = ctor.newInstance("", "", false);

        Method toEmpty = DeprecatedAttributes.class.getDeclaredMethod("toEmpty", String.class);
        toEmpty.setAccessible(true);

        Object resultNull = toEmpty.invoke(instance, (Object) null);
        assertEquals("", resultNull);

        Object resultNonNull = toEmpty.invoke(instance, "xyz");
        assertEquals("xyz", resultNonNull);
    }
}

